/**
 * advisor-recommendation.tsx
 * Centralized AdvisorRecommendations rendering and text mapping.
 */
import { For, Show, splitProps, type Component, type JSX, type ParentComponent } from "solid-js";

import { L10n } from "#core/ui-next/components/l10n.jsx";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";

import { AdvisorRecommendations as AdvisorRecommendationsType } from "#base/ui/tutorial/advisor-utilities.js";

/**
 * Returns the localization key for a given advisor recommendation type.
 */
export const getTextForAdvisorRecommendation = (type: AdvisorRecommendationsType): string => {
	switch (type) {
		case "recommendation-cultural":
			return "LOC_UI_RECOMMENDATION_CULTURAL";
		case "recommendation-economic":
			return "LOC_UI_RECOMMENDATION_ECONOMIC";
		case "recommendation-military":
			return "LOC_UI_RECOMMENDATION_MILITARY";
		case "recommendation-scientific":
			return "LOC_UI_RECOMMENDATION_SCIENCE";
		default:
			return "LOC_UI_RECOMMENDATION_DEFAULT";
	}
};

/**
 * Returns the icon URL for a given advisor recommendation type.
 */
export const getIconForAdvisorRecommendation = (rec: AdvisorRecommendationsType): string => {
	switch (rec) {
		case "recommendation-cultural":
			return "blp:adv_gem_cultural.png";
		case "recommendation-economic":
			return "blp:adv_gem_economic.png";
		case "recommendation-military":
			return "blp:adv_gem_militaristic.png";
		case "recommendation-scientific":
			return "blp:adv_gem_scientific.png";
		default:
			return "";
	}
};

// #region Advisor Recommendation Item

export interface AdvisorRecommendationItemProps extends JSX.HTMLAttributes<HTMLDivElement> {
	/** The advisor recommendation type to display. */
	recommendation: AdvisorRecommendationsType;
	/** If true, only shows the icon without text. */
	iconOnly?: boolean;

	/** Optional size class for the icon container (e.g., 'size-6'). */
	sizeClass?: `size-${number}`;

	/** text to override the advisor recommendation label */
	textOverride?: string;
}

/**
 * Renders a single advisor recommendation with icon and optional localized label.
 */
export const AdvisorRecommendationItem: Component<AdvisorRecommendationItemProps> = (props) => {
	const [local, other] = splitProps(props, ["recommendation", "iconOnly", "sizeClass", "class", "textOverride"]);
	const text = () => {
		return local.textOverride ?? getTextForAdvisorRecommendation(local.recommendation);
	};
	return (
		<div
			class={`flex flex-auto items-center ${local.class ?? ""}`}
			{...other}
		>
			<div
				class={`bg-no-repeat bg-contain mr-2 flex ${local.sizeClass ?? "size-6"}`}
				style={{ "background-image": `url(${getIconForAdvisorRecommendation(local.recommendation)})` }}
			/>
			<Show when={!local.iconOnly}>
				<L10n.Stylize
					class="flex flex-auto flex-wrap"
					text={text()}
				/>
			</Show>
		</div>
	);
};

// #endregion

// #region Advisor Recommendations List

export interface AdvisorRecommendationsListProps extends JSX.HTMLAttributes<HTMLDivElement> {
	recommendations: AdvisorRecommendationsType[];
	direction?: "horizontal" | "vertical";
	iconOnly?: boolean;
	noWrap?: boolean;
}

const AdvisorRecommendationsListComponent: ParentComponent<AdvisorRecommendationsListProps> = (props) => {
	const [local, other] = splitProps(props, ["recommendations", "direction", "iconOnly", "class", "noWrap"]);
	const direction = () => (local.direction === "vertical" ? "flex-col" : "flex-row");

	const wrapClass = () => ((local.noWrap !== true) ? "flex-wrap" : "");
	return (
		<Show when={local.recommendations.length > 0}>
			<div
				class={`relative flex ${direction()} ${wrapClass()} items-center justify-center font-body ${local.class ?? ""}`}
				{...other}
			>
				<For each={local.recommendations}>
					{(rec) => (
						<div class="my-1">
							<AdvisorRecommendationItem
								recommendation={rec}
								iconOnly={local.iconOnly}
							/>
						</div>
					)}
				</For>
			</div>
		</Show>
	);
};

/**
 * Renders a list of advisor recommendations with icons and localized labels.
 */
export const AdvisorRecommendationsList = ComponentRegistry.register({
	name: "AdvisorRecommendationsList",
	createInstance: AdvisorRecommendationsListComponent,
});

// #endregion
